        return g
    sr, sc = start
    row_walls = [r for r in range(h) if sum(v == 8 for v in g[r]) >= max(3, 0.6 * w)]
    col_walls = [c for c in range(w) if sum(g[r][c] == 8 for r in range(h)) >= max(3, 0.6 * h)]
    horizontal = len(row_walls) >= len(col_walls)
    if horizontal:
        walls = row_walls
        axis_start, cross_start = sr, sc
        axis_len, cross_len = h, w
        sign = 1 if (not walls or sr < min(walls)) else -1
        if min(walls, default=sr) < sr < max(walls, default=sr):
            sign = 1 if abs(sr - min(walls)) <= abs(sr - max(walls)) else -1
        walls = sorted([x for x in walls if (x - sr) * sign > 0], reverse=sign < 0)
        def get(r, c): return g[r][c]
        def put(axis, cross):
            if 0 <= axis < h and 0 <= cross < w and g[axis][cross] == 0:
                g[axis][cross] = 2
        def wall_holes(axis): return [c for c in range(w) if g[axis][c] == 0]
        def lane_put(wall, cross): put(wall - sign, cross)
        def corridor_put(axis, cross): put(axis, cross)
    else:
        walls = col_walls
        axis_start, cross_start = sc, sr
        axis_len, cross_len = w, h
        sign = 1 if (not walls or sc < min(walls)) else -1
        if min(walls, default=sc) < sc < max(walls, default=sc):
            sign = 1 if abs(sc - min(walls)) <= abs(sc - max(walls)) else -1
        walls = sorted([x for x in walls if (x - sc) * sign > 0], reverse=sign < 0)
        def get(r, c): return g[r][c]
        def put(axis, cross):
            if 0 <= axis < w and 0 <= cross < h and g[cross][axis] == 0:
                g[cross][axis] = 2
        def wall_holes(axis): return [r for r in range(h) if g[r][axis] == 0]
        def lane_put(wall, cross): put(wall - sign, cross)
        def corridor_put(axis, cross): put(axis, cross)
    if not walls:
        return g
    active = [cross_start]
    previous_axis = axis_start
    for i, wall in enumerate(walls):
        holes = wall_holes(wall)
        selected = set()
        for a in active:
            if a in holes:
                selected.add(a)
            else:
                below = [x for x in holes if x < a]
                above = [x for x in holes if x > a]
                if below:
                    selected.add(max(below))
                if above:
                    selected.add(min(above))
        if not selected:
            break
        selected = sorted(selected)
        # Connect the marker or prior corridor to the lane beside this wall.
        lane_axis = wall - sign
        if i == 0:
            for a in range(min(axis_start, lane_axis), max(axis_start, lane_axis) + 1):
                corridor_put(a, cross_start)
        # Color the approach lane along the selected openings.
        if len(selected) > 1:
            lo, hi = selected[0], selected[-1]
        else:
            x = selected[0]
            if all(a < x for a in active):
                lo, hi = 0, x
            elif all(a > x for a in active):
                lo, hi = x, cross_len - 1
            else:
                lo, hi = 0, cross_len - 1
        for cross in range(lo, hi + 1):
            lane_put(wall, cross)
        for cross in selected:
            put(wall, cross)
        # Continue through each selected opening toward the next wall or edge.
        if i + 1 < len(walls):
            stop = walls[i + 1]
            if sign > 0:
                axes = range(wall + 1, stop)
            else:
                axes = range(wall - 1, stop, -1)
        else:
            axes = range(wall + sign, axis_len if sign > 0 else -1, sign)
        for axis in axes:
            for cross in selected:
                corridor_put(axis, cross)
        active = selected
    return g
